package com.pandinila.broadband_management.service;
import com.pandinila.broadband_management.entity.*; import com.pandinila.broadband_management.entity.Enums.*; import com.pandinila.broadband_management.prediction.*; import com.pandinila.broadband_management.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class MonitoringService { private final NetworkMetricRepository metrics; private final ServiceQualityRepository qualities; private final ComplaintPredictionRepository predictions; private final ComplaintPredictionEngine engine;
 public MonitoringService(NetworkMetricRepository m,ServiceQualityRepository q,ComplaintPredictionRepository p,ComplaintPredictionEngine e){metrics=m;qualities=q;predictions=p;engine=e;}
 @Transactional public ComplaintPrediction process(NetworkMetric metric){ metrics.save(metric); double score=quality(metric); ServiceQuality q=new ServiceQuality();q.setCustomer(metric.getCustomer());q.setNetworkMetric(metric);q.setQualityScore(score);q.setQualityLevel(qualityLevel(score));qualities.save(q); List<NetworkMetric> history=metrics.findTop20ByCustomerOrderByTimestampDesc(metric.getCustomer()); boolean declining=history.size()>2 && metric.getLatency()>history.get(history.size()-1).getLatency()+10; PredictionResult r=engine.evaluate(metric,score,declining,metric.getCustomer().getPreviousComplaintCount()); ComplaintPrediction p=new ComplaintPrediction();p.setCustomer(metric.getCustomer());p.setRiskScore(r.score());p.setRiskLevel(r.level());p.setPrediction(r.prediction());p.setPredictionWindow(r.window());p.setReasons(String.join(" | ",r.reasons()));return predictions.save(p); }
 public double quality(NetworkMetric m){ double speed=Math.min(100,m.getDownloadSpeed()); double latency=Math.max(0,100-m.getLatency()*0.6); double loss=Math.max(0,100-m.getPacketLoss()*12); double signal=Math.max(0,Math.min(100,(m.getSignalStrength()+100)*2)); return round(speed*.25+latency*.22+loss*.22+signal*.13+m.getConnectionStability()*.18); } private double round(double d){return Math.round(d*100.0)/100.0;} private QualityLevel qualityLevel(double s){return s>=80?QualityLevel.EXCELLENT:s>=60?QualityLevel.GOOD:s>=40?QualityLevel.FAIR:QualityLevel.POOR;}
 public Optional<NetworkMetric> latestMetric(Customer c){return metrics.findTopByCustomerOrderByTimestampDesc(c);} public Optional<ServiceQuality> latestQuality(Customer c){return qualities.findTopByCustomerOrderByIdDesc(c);} public Optional<ComplaintPrediction> latestPrediction(Customer c){return predictions.findTopByCustomerOrderByIdDesc(c);} public List<NetworkMetric> history(Customer c){return metrics.findTop20ByCustomerOrderByTimestampDesc(c);}
}
